parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "location": {
      "type": "string",
      "description": "City or place name, e.g. Cox's Bazar"
    },
    "budget": {
      "type": "string",
      "description": "Optional. One of: budget, mid-range, luxury"
    }
  },
  "required": ["location"]
}
